import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict(side, price, qty, seq)
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def clean_buy_top():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or info['side'] != 'buy' or info['qty'] <= 0 or info['seq'] != seq:
                heapq.heappop(buy_heap)
                continue
            return True
        return False

    def clean_sell_top():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or info['side'] != 'sell' or info['qty'] <= 0 or info['seq'] != seq:
                heapq.heappop(sell_heap)
                continue
            return True
        return False

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['qty'] > 0:
                info['qty'] = 0
                # leave in dict but qty=0 marks as removed/filled/cancelled
                # (lazy deletion from heap handles removal)
            continue

        oid = order[1]
        side = order[2]
        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        remaining = qty

        if side == 'buy':
            while remaining > 0 and clean_sell_top():
                sprice, sseq, sid = sell_heap[0]
                if typ != 'market' and price is not None:
                    if sprice > price:
                        break
                sinfo = book[sid]
                trade_qty = min(remaining, sinfo['qty'])
                trades.append([oid, sid, sprice, trade_qty])
                remaining -= trade_qty
                sinfo['qty'] -= trade_qty
                if sinfo['qty'] <= 0:
                    heapq.heappop(sell_heap)
        else:
            while remaining > 0 and clean_buy_top():
                negprice, bseq, bid = buy_heap[0]
                bprice = -negprice
                if typ != 'market' and price is not None:
                    if bprice < price:
                        break
                binfo = book[bid]
                trade_qty = min(remaining, binfo['qty'])
                trades.append([bid, oid, bprice, trade_qty])
                remaining -= trade_qty
                binfo['qty'] -= trade_qty
                if binfo['qty'] <= 0:
                    heapq.heappop(buy_heap)

        if typ == 'limit' and remaining > 0:
            seq_counter += 1
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq_counter}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, seq_counter, oid))
        # ioc/market: discard remainder, no book entry

    return trades

